<template><view class="course-selector"><text class="small muted">{{course.current.title}} · {{course.current.abilityLevels.join(' / ')}}</text><picker :range="course.installed" range-key="title" :value="index" aria-label="选择学习课程" @change="choose"><view class="course-picker"><text>{{course.current.title}}</text><text aria-hidden="true">⌄</text></view></picker><picker :range="course.lessons" range-key="name" :value="lessonIndex" aria-label="选择课节起点" @change="course.chooseLesson(course.lessons[+($event as any).detail.value].id)"><view class="course-picker small"><text>{{course.lesson?.unit}} · {{course.lesson?.name}}</text><text aria-hidden="true">⌄</text></view></picker><text class="small muted">能力起点 {{profile.db.abilityLevel||'L1'}} · {{course.current.abilityLevels.includes(profile.db.abilityLevel||'L1')?'当前课程适合此起点':'可请家长选择匹配此起点的课程'}}</text><text v-if="profile.db.pendingCourseId" class="small muted">先继续当前学习，已保留待切换课程。</text></view></template>
<script setup lang="ts">
import {computed} from 'vue';import {useCourseStore} from '../../stores/course';import {useProfileStore} from '../../stores/profile'
const course=useCourseStore(),profile=useProfileStore(),index=computed(()=>course.installed.findIndex(c=>c.courseId===course.currentId)),lessonIndex=computed(()=>course.lessons.findIndex(l=>l.id===course.lesson?.id))
function choose(event:any){const id=course.installed[+event.detail.value]?.courseId;if(id)course.choose(id)}
</script>
